-- IPA source-verified 2022 December basics and exact 2020 July repeats.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2022-20221211-q01','exam-fe','桁落ち','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問1・改編】桁落ちの説明として適切なものはどれか。','[{"id":"a","text":"ほぼ等しい浮動小数点数同士の減算で有効桁数が大幅に減る"},{"id":"b","text":"演算結果が表現できる最大値を超える"},{"id":"c","text":"最小桁より小さい部分を四捨五入・切上げ・切捨てすることで誤差が生じる"},{"id":"d","text":"浮動小数点数の加算で片方の数値の下位桁が結果に反映されない"}]','"a"','近い値の差を取ると上位桁が相殺され、有効桁数が減る。 中文：两个接近的浮点数相减时高位抵消，有效位数减少，称为相消误差。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20221211-q02','exam-fe','待ち行列','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問2・改編】平均待ち時間=平均伝送時間×回線利用率/(1−回線利用率)。利用率を0から増やすとき、平均待ち時間が平均伝送時間を初めて上回るのは利用率が幾つを超えたときか。','[{"id":"a","text":"0.4"},{"id":"b","text":"0.5"},{"id":"c","text":"0.6"},{"id":"d","text":"0.7"}]','"b"','ρ/(1−ρ)>1を解くとρ>0.5。 中文：解不等式ρ/(1−ρ)>1可得利用率超过0.5。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20221211-q03','exam-fe','マルコフ過程','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問3・改編】天気の翌日への遷移確率は、晴れ→晴れ40%・曇り40%・雨20%、曇り→晴れ30%・曇り40%・雨30%、雨→晴れ30%・曇り50%・雨20%。単純マルコフ過程として、雨の2日後が晴れである確率は何％か。','[{"id":"a","text":"15"},{"id":"b","text":"27"},{"id":"c","text":"30"},{"id":"d","text":"33"}]','"d"','翌日が晴れ・曇り・雨となる各経路の確率を足す。0.3×0.4+0.5×0.3+0.2×0.3=0.33。 中文：分别计算次日三种天气再转晴的概率，相加得到33%。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20221211-q04','exam-fe','計算量','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問4・改編】連立一次方程式の計算時間は未知数の個数の3乗に比例する。あるコンピュータで100元に2秒かかるとき、演算速度4倍のコンピュータで1,000元に何秒かかるか。','[{"id":"a","text":"5"},{"id":"b","text":"50"},{"id":"c","text":"500"},{"id":"d","text":"5,000"}]','"c"','未知数10倍で計算量1,000倍、速度4倍で時間は2×1,000÷4=500秒。 中文：未知数增至10倍，工作量增至1000倍；速度4倍后耗时500秒。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20221211-q05','exam-fe','ディープラーニング','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問5・改編】AIのディープラーニングに最も関連が深いものはどれか。','[{"id":"a","text":"特定分野の専門知識を使いルールベースで推論する"},{"id":"b","text":"試行錯誤と場合分けを深さ優先で探索し、解がなければ前の状態に戻る"},{"id":"c","text":"神経回路網を模倣した多層モデルのパラメータを調整し適切な出力を得る"},{"id":"d","text":"解の候補を遺伝子に見立て突然変異や交配を繰り返す"}]','"c"','多層ニューラルネットワークを用いる深層学習が該当する。他はルール推論、探索、遺伝的アルゴリズム。 中文：深度学习使用多层神经网络并调整参数学习。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20221211-q06','exam-fe','偶数パリティ','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問6・改編】7ビット文字コード30、3F、7A（16進）の先頭に偶数パリティビットを1ビット付加した結果はどれか。','[{"id":"a","text":"30、3F、7A"},{"id":"b","text":"30、3F、FA"},{"id":"c","text":"B0、3F、FA"},{"id":"d","text":"B0、BF、7A"}]','"b"','30は1が2個、3Fは6個で先頭0。7Aは5個で先頭1を付け、FAになる。 中文：30和3F已有偶数个1，7A有5个1，最高位补1变为FA。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20221211-q07','exam-fe','隣接行列と木','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問7・改編】頂点1〜5の無向グラフの辺が次のいずれかである。木となるものはどれか。各組(i,j)は頂点iとjを結ぶ辺を表す。','[{"id":"a","text":"(1,2),(1,5),(2,3),(3,4),(4,5)"},{"id":"b","text":"(1,2),(1,5),(2,3),(2,4)"},{"id":"c","text":"(1,2),(1,4),(2,3),(3,4),(3,5)"},{"id":"d","text":"(1,2),(1,3),(2,3),(3,4),(3,5),(4,5)"}]','"b"','5頂点の連結グラフで辺が4本、閉路がないBが木。他の選択肢には閉路がある。 中文：5个顶点连通且只有4条边、没有环的选项B是树。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20221211-q08','exam-fe','バブルソート','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問8・改編】バブルソートの説明はどれか。','[{"id":"a","text":"一定間隔で取り出した部分列を並べ替え、間隔を縮めて繰り返す"},{"id":"b","text":"基準値より大きいものと小さいものに分け、各区分で繰り返す"},{"id":"c","text":"隣り合う要素を比較し、逆順なら交換する操作を繰り返す"},{"id":"d","text":"未整列部分の最小値を取り出し整列済み部分に移す"}]','"c"','隣接要素の比較と交換を繰り返すのがバブルソート。 中文：冒泡排序反复比较相邻元素并交换逆序元素。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20221211-q09','exam-fe','線形探索','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問9・改編】整数配列A[1..N]（N>1）からXを探索する。k=1とし、k>Nなら終了、A[k]=Xなら終了、それ以外はkを1増やして繰り返す。実行結果として適切なものはどれか。','[{"id":"a","text":"Xがない場合k=1"},{"id":"b","text":"Xがない場合k=N"},{"id":"c","text":"Xが1番目とN番目にある場合k=1"},{"id":"d","text":"Xが1番目とN番目にある場合k=N"}]','"c"','先頭から調べ最初の一致で終了する。見つからなければk=N+1、一致が1番目にあればk=1。 中文：顺序搜索在首次匹配时停止；未找到则k为N+1。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20221211-q10','exam-fe','再帰関数','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問10・改編】自然数nについてf(n)=1（n≤1）、それ以外はn+f(n−1）と定義する。f(5)はいくつか。','[{"id":"a","text":"6"},{"id":"b","text":"9"},{"id":"c","text":"15"},{"id":"d","text":"25"}]','"c"','f(5)=5+4+3+2+1=15。 中文：递归展开后为1到5之和15。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20221211-q11','exam-fe','外部割込み','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問11・改編】外部割込みに分類されるものはどれか。','[{"id":"a","text":"インターバルタイマで指定時間が経過したときの割込み"},{"id":"b","text":"演算結果のオーバーフローやゼロ除算による割込み"},{"id":"c","text":"仮想記憶で存在しないページにアクセスしたときの割込み"},{"id":"d","text":"ソフトウェア割込み命令の実行による割込み"}]','"a"','タイマによる通知は外部割込み。演算例外・ページフォールト・ソフトウェア命令は内部要因。 中文：定时器时间到触发外部中断；运算异常和缺页由内部执行引发。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20221211-q12','exam-fe','CPIと処理時間','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問12・改編】同じ命令セットのコンピュータAとBで同じプログラムを実行する。Aはクロック周期1ナノ秒・CPI4.0、Bは周期4ナノ秒・CPI0.5。Aの処理時間はBの何倍か。','[{"id":"a","text":"1/32"},{"id":"b","text":"1/2"},{"id":"c","text":"2"},{"id":"d","text":"8"}]','"c"','同じ命令数について、Aは1×4=4ナノ秒/命令、Bは4×0.5=2ナノ秒/命令。Aは2倍。 中文：每条指令平均耗时A为4纳秒、B为2纳秒，因此A为2倍。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20221211-q21','exam-fe','チャタリング','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問21・改編】機械式接点の押しボタンを1回押した後、数ミリ秒の間にON/OFFが複数回発生する現象はどれか。','[{"id":"a","text":"サンプリング"},{"id":"b","text":"シェアリング"},{"id":"c","text":"チャタリング"},{"id":"d","text":"バッファリング"}]','"c"','機械接点の跳ね返りで短時間にON/OFFを繰り返す現象はチャタリング。 中文：机械触点弹跳造成短时间多次通断，称为抖动。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption');
